prospects=[]
for i,r in enumerate(rows,1):
 name,location,tier,product,contact,route,evidence,angle,qualifier,opening=r
 msg=f"Hi {name},\n\n{opening}\n\nI’m developing Formdesk, a browser-based desk configurator. I have a working concept demo and a proposed $500 USD pilot for one simple desk model, your branding and pricing rules, and quote delivery to your inbox.\n\nWould you be open to a 15-minute conversation to see whether it fits your process?\n\n[Your name]\nFormdesk\n\nIf this is not relevant, let me know and I won’t follow up."
 prospects.append(dict(rank=i,name=name,location=location,priority=tier,product_url=product,contact_source=contact,contact_route=route,observed=evidence,hypothesis=angle,qualification=qualifier,subject=f'3D configuration for one {name} desk',draft=msg,status='Not contacted',checked='2026-10-28'))
(p/'prospects.json').write_text(json.dumps(prospects,indent=2,ensure_ascii=False))
e=html.escape
cards=''
for x in prospects:
 cards+=f'''<article><div class="top"><span class="num">{x['rank']:02}</span><div><h2>{e(x['name'])}</h2><p>{e(x['location'])} · Priority {e(x['priority'])} · Not contacted</p></div></div><div class="links"><a href="{e(x['product_url'])}">Product / business evidence ↗</a><a href="{e(x['contact_source'])}">Contact source ↗</a></div><p><b>Public contact route:</b> {e(x['contact_route'])}</p><p><b>Observed:</b> {e(x['observed'])}</p><p><b>Proposed angle — inference:</b> {e(x['hypothesis'])}</p><p class="qualification"><b>Qualify before pitching:</b> {e(x['qualification'])}</p><details><summary>Personalized outreach draft</summary><p><b>Subject:</b> {e(x['subject'])}</p><pre>{e(x['draft'])}</pre></details></article>'''
